import{j as e}from"./react-core-mh6p-iwg.js";import{S as i}from"./ServiceLandingTemplate-BOhZtiCT.js";import{s as a}from"./real_tiling_works-BXOvNWz7.js";import{B as t,h as r,x as l,y as o,S as n,I as s,f as d,W as c,t as u,Z as g}from"./icons-u4fHCtTm.js";import"./index-CbIPdv14.js";import"./radix-BW_Nv8wV.js";import"./vendor-CKb7fRZ8.js";import"./tanstack-DghZwqDz.js";import"./router-ierbK2-F.js";import"./seo-Be9W7RVd.js";import"./SEO-BWZt0E9o.js";const p=[{icon:t,title:"Cracked Tiles",desc:"Cracked or broken tiles are a tripping hazard, look unsightly, and allow water to penetrate beneath."},{icon:r,title:"Stained Grout",desc:"Discolored, dark grout that cleaning won't fix — it's time for grout restoration or full retiling."},{icon:n,title:"Hollow-Sounding Tiles",desc:"Tiles that sound hollow when tapped — they've debonded from the substrate and will eventually crack."},{icon:s,title:"Water Seeping Through",desc:"Water leaking through tile joints in wet areas causing dampness, mold, and structural damage below."},{icon:d,title:"Outdated Tile Design",desc:"Old-fashioned tiles that make your space look dated and reduce your property's market value."},{icon:c,title:"Uneven Tile Surfaces",desc:"Noticeable height differences between adjacent tiles creating an unsafe floor and poor aesthetic."}],m=[{icon:t,title:"Marble & Porcelain Laying",desc:"Precision installation of marble, porcelain, ceramic, and mosaic tiles with laser-guided leveling."},{icon:r,title:"Full Waterproofing",desc:"Waterproofing membrane applied beneath all wet area tiles preventing future water damage."},{icon:l,title:"Grout Restoration & Sealing",desc:"Premium grout color-matched, applied, and sealed to resist staining, moisture, and mold growth."},{icon:o,title:"Tile Removal & Replacement",desc:"Safe removal of old tiles, substrate preparation, and fresh installation with precision alignment."}],h=[{num:"01",title:"Step 1: Design Consultation",desc:"We help you choose tile patterns, layouts, size, and grout colors to match your vision and budget."},{num:"02",title:"Step 2: Surface Preparation",desc:"Substrate leveled, waterproofed, and primed for a perfect adhesion bond — no shortcuts taken."},{num:"03",title:"Step 3: Precision Laying",desc:"Laser-guided tile installation ensures perfectly straight lines, even spacing, and zero lippage."},{num:"04",title:"Step 4: Grouting & Sealing",desc:"Premium grout applied with precision, cleaned, and sealed to resist staining and moisture ingress."},{num:"05",title:"Step 5: Quality Inspection",desc:"Every tile tapped to confirm solid bond, edges inspected, and site cleaned before handover."}],f=[{name:"Hamad Al Khoury",area:"Jumeirah Village",review:"Full villa floor retiling done perfectly. Zero lippage, perfectly straight lines and the marble finish is absolutely stunning. A truly professional team."},{name:"Claire Beaumont",area:"Downtown Dubai",review:"Bathroom retiling done beautifully. They matched the existing marble perfectly and the grouting is flawless. No mess whatsoever. Highly recommended."},{name:"Rajan Nambiar",area:"Dubai Marina",review:"Large format porcelain laid in the living room — the result is breathtaking. They were meticulous about leveling and the finish is perfect. Great team."}],b=[{q:"How long does bathroom tiling take?",a:"A standard bathroom (5–8 sqm of wall and floor tiling) takes 2–3 days including drying time for tile adhesive and grout to fully cure."},{q:"Can you remove and replace existing tiles?",a:"Yes. We carefully break out old tiles, thoroughly prepare the substrate, and lay new tiles cleanly — minimizing damage to surrounding areas."},{q:"Do you supply tiles or should I purchase them?",a:"Both options work. We can source tiles through our trade supplier network at competitive prices, or work with tiles you have already purchased."},{q:"What is the difference between ceramic and porcelain?",a:"Porcelain is denser, less porous, and more durable — ideal for heavy-traffic areas and wet spaces. Ceramic is lighter and easier to cut — great for walls and low-traffic floors."},{q:"What does zero lippage mean?",a:"Lippage refers to height differences between adjacent tiles. Zero lippage means every tile surface is perfectly flush with its neighbors — the hallmark of premium installation."},{q:"Can you lay large format tiles (60x60 or 120x60)?",a:"Yes — large format tiles are our specialty. They require advanced leveling systems and experienced hands to install correctly without lippage or cracking."},{q:"Do you do outdoor tiling and pavers?",a:"Yes. We install outdoor ceramic, porcelain, and natural stone pavers for terraces, pool surrounds, garden paths, and building exteriors across Dubai."}],v=[{icon:u,label:"Starting Price",value:"AED 25/sqm",colorClass:"bg-gold/15 text-gold",valueClass:"text-gold"},{icon:g,label:"Zero Lippage",value:"Guaranteed",colorClass:"bg-[#22c55e]/15 text-[#22c55e]",valueClass:"text-slate-900"},{icon:n,label:"Waterproof",value:"Membrane",colorClass:"bg-gold/15 text-gold",valueClass:"text-slate-900"}],w=[{to:"/services/plaster-works",emoji:"🏗️",label:"professional plastering services Dubai"},{to:"/services/painting",emoji:"🎨",label:"professional painting services Dubai"},{to:"/services/plumbing",emoji:"🚿",label:"emergency plumbing services Dubai"}],y=()=>e.jsx(i,{seo:{title:"Tiling Services Dubai | Floor & Wall Tiling | Afnan",description:"Professional floor and wall tiling in Dubai. Marble, porcelain & ceramic installation with zero lippage guarantee. Waterproofing included. Licensed LLC. Free quote!",keywords:"tiling services Dubai, floor tiling Dubai, wall tiling Dubai, marble installation Dubai, porcelain tile Dubai, bathroom tiling Dubai, tiling contractor Dubai, tile replacement Dubai, grout repair Dubai, outdoor tiling Dubai",canonicalUrl:"/services/tiling",ogImage:"https://maresidentialpropertycareservicellc.com/og-images/tiling-dubai.jpg"},heroImage:a,h1Plain:"Professional Floor & Wall",h1Gradient:"Tiling Services Dubai",heroTag:"Zero Lippage Guarantee on Every Project",heroSubtitle:"Marble, Porcelain & Ceramic Tile Installation for Villas, Apartments & Commercial Spaces",heroDesc:"Laser-leveled, precision tile installation with full waterproofing and premium grout — delivered by experienced tiling specialists across Dubai.",heroBadges:["Zero Lippage Guarantee","Licensed LLC","Waterproofing Included","All Dubai Areas"],floatingCards:v,warningSigns:p,warningTitle:"Is Your Tiling Showing These Problems?",warningSubtitle:"Tile damage and deteriorating grout worsen with time and water exposure. Our tiling specialists can restore your floors and walls perfectly.",beforeAfter:{title:"Before vs After Professional Tiling",subtitle:"See the stunning transformation our precision tiling service delivers to Dubai properties.",before:["Cracked, chipped, and hollow tiles","Stained, deteriorated grout lines","Water leaking through wet area joints","Uneven floor with noticeable tile lippage"],after:["Pristine, zero-lippage tile installation","Clean, sealed, professional grout lines","Fully waterproofed and sealed wet areas","Laser-level smooth, perfectly even surfaces"]},includedServices:m,includedTitle:"Complete Tiling Services in Dubai",includedSubtitle:"From marble to large-format porcelain — our certified tiling team delivers flawless results on every project.",processSteps:h,processTitle:"Our 5-Step Professional Tiling Process",processSubtitle:"Precision tile installation engineered for perfect results in Dubai's residential and commercial properties.",stats:[["50,000+","sqm Tiled"],["4.9★","Customer Rating"],["All Types","Tiles Handled"],["100%","Zero Lippage"]],reviews:f,faqs:b,faqTitle:"Frequently Asked Questions About Tiling Services in Dubai",faqSubtitle:"Direct answers to the most common questions about our floor and wall tiling services.",serviceSlug:"tiling",serviceName:"Floor & Wall Tiling",ctaHeading:"Ready to Transform Your Floors & Walls?",ctaSubtitle:"Get a free tiling consultation and quote — anywhere in Dubai.",formUnitLabel:"Area to be Tiled",formUnitOptions:[{value:"Bathroom",label:"Bathroom / Wet Area"},{value:"Kitchen",label:"Kitchen Flooring"},{value:"Living Room",label:"Living Room / Hallway"},{value:"Outdoor",label:"Terrace / Pool Area"},{value:"Full Apartment",label:"Full Apartment"},{value:"Villa",label:"Villa / Townhouse"}],internalLinks:w});export{y as default};
